('Bamburi Sea Breeze Apartment', 'Airbnb', 'Bamburi, Mombasa', 5500, 120000, 2, 2, 980, 4, true, true, 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=1200&q=80', ARRAY['https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=1200&q=80','https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=1200&q=80'], 'Bright modern 2-bed apartment with sea breeze balcony, swimming pool, and 24/7 security. 5 minutes to Bamburi beach.', 'https://maps.google.com/?q=Bamburi+Beach+Mombasa', 'NS-BA002'),
('Diani Palm Suites', 'Airbnb', 'Diani, Kwale', 12000, 250000, 4, 3, 2100, 8, true, true, 'https://images.unsplash.com/photo-1582719508461-905c673771fd?w=1200&q=80', ARRAY['https://images.unsplash.com/photo-1564013799919-ab600027ffc6?w=1200&q=80','https://images.unsplash.com/photo-1570129477492-45c003edd2be?w=1200&q=80'], 'Luxury 4-bedroom villa under swaying palms. Walking distance to Diani white sands, equipped with chef-grade kitchen, BBQ deck, and outdoor lounge.', 'https://maps.google.com/?q=Diani+Beach', 'NS-DI003'),
('Mombasa Old Town Loft', 'Airbnb', 'Old Town, Mombasa', 4000, 80000, 1, 1, 620, 2, true, false, 'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?w=1200&q=80', ARRAY['https://images.unsplash.com/photo-1505691938895-1758d7feb511?w=1200&q=80','https://images.unsplash.com/photo-1493663284031-b7e3aefcae8e?w=1200&q=80'], 'Charming heritage loft in the heart of Old Town with restored Swahili interiors, walking distance to Fort Jesus and the spice market.', 'https://maps.google.com/?q=Fort+Jesus+Mombasa', 'NS-OT004'),
('Shanzu Garden Penthouse', 'Airbnb', 'Shanzu, Mombasa', 9500, 200000, 3, 2, 1700, 6, true, true, 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=1200&q=80', ARRAY['https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?w=1200&q=80','https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=1200&q=80'], 'Spacious top-floor penthouse with private rooftop garden, panoramic ocean views, and direct beach access via Serena gate.', 'https://maps.google.com/?q=Shanzu+Beach+Mombasa', 'NS-SH005'),
('Mtwapa Creek House', 'Rental', 'Mtwapa, Kilifi', 0, 95000, 3, 2, 1300, 6, true, false, 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1200&q=80', ARRAY['https://images.unsplash.com/photo-1568605114967-8130f3a36994?w=1200&q=80','https://images.unsplash.com/photo-1600047509807-ba8f99d2cdde?w=1200&q=80'], 'Family-friendly long-term rental on the Mtwapa creek. 3 spacious bedrooms, garden, parking and quick access to Mombasa city.', 'https://maps.google.com/?q=Mtwapa+Creek', 'NS-MT006'),
('Nyali Ocean Studio', 'Airbnb', 'Nyali, Mombasa', 3500, 70000, 1, 1, 480, 2, true, false, 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=1200&q=80', ARRAY['https://images.unsplash.com/photo-1502005229762-cf1b2da7c5d6?w=1200&q=80','https://images.unsplash.com/photo-1554995207-c18c203602cb?w=1200&q=80'], 'Cozy ocean-view studio perfect for solo travelers and couples. Fully serviced, fast Wi-Fi, gym and pool access included.', 'https://maps.google.com/?q=Nyali+Mombasa', 'NS-NS007'),
('Tudor Modern 2-Bed', 'Rental', 'Tudor, Mombasa', 0, 65000, 2, 1, 850, 4, true, false, 'https://images.unsplash.com/photo-1493606278519-11aa9f86e40a?w=1200&q=80', ARRAY['https://images.unsplash.com/photo-1484154218962-a197022b5858?w=1200&q=80','https://images.unsplash.com/photo-1507089947368-19c1da9775ae?w=1200&q=80'], 'Affordable modern 2-bedroom apartment in Tudor estate. Ideal for professionals and small families seeking long-term housing in Mombasa.', 'https://maps.google.com/?q=Tudor+Mombasa', 'NS-TU008');